  const legacyAuth = read('focusly.auth.v1', null);
  if (!legacyAuth?.account?.email) return accounts;
  const id = uid('account');
  accounts[id] = { id, email: legacyAuth.account.email, salt: legacyAuth.account.salt, verifier: legacyAuth.account.verifier, createdAt: new Date().toISOString() };
  const migrated = createState(accounts[id]);
  migrated.profile = read('focusly.profile.v1', { ...DEFAULTS });
  migrated.preferences = { ...DEFAULTS, ...read('focusly.preferences.v1', {}) };
  migrated.onboarding = read('focusly.onboarding.v1', { completed:false });
  migrated.resources = read('focusly.resources.v1', []);
  migrated.notes = read('focusly.notes.v1', []);
  migrated.decks = normalizeDecks(read('focusly.decks.v1', []));
