function normalizeDecks(decks) { return (Array.isArray(decks) ? decks : []).map(deck => ({ ...deck, id: deck.id || uid('deck'), cards: (deck.cards || []).map(card => ({ ...card, id: card.id || uid('card'), review: { dueAt:null, rating:null, reviewCount:0, intervalDays:0, easeFactor:2.5, state:'new', lapses:0, ...(card.review || {}) } })) })); }
