function beginOnboarding() { $('#onboarding-name').value = ''; $('#onboarding-weekly-goal').value = DEFAULTS.weeklyGoalMinutes; $('#onboarding-daily-goal').value = DEFAULTS.dailyGoalMinutes; $('#onboarding-error').textContent = ''; showAccess('onboarding'); }
