function rateCard(rating) { const deck = currentState.decks.find(item => item.id === reviewState.deckId); const card = deck?.cards[reviewState.cardIndex]; if (!card) return; const review = { intervalDays:0, easeFactor:2.5, reviewCount:0, lapses:0, state:'new', ...(card.review || {}) }; const intervals = { again:0, hard:Math.max(1, Math.round((review.intervalDays || 1) * 1.2)), good:review.intervalDays < 1 ? 1 : Math.max(3, Math.round(review.intervalDays * review.easeFactor)), easy:review.intervalDays < 1 ? 4 : Math.max(7, Math.round(review.intervalDays * (review.easeFactor + 0.3))) }; if (rating === 'again') { review.state = 'learning'; review.intervalDays = 0; review.lapses += 1; review.easeFactor = Math.max(1.3, review.easeFactor - 0.2); } else { review.intervalDays = intervals[rating]; review.state = review.intervalDays >= 21 ? 'mastered' : 'review'; review.easeFactor = Math.max(1.3, review.easeFactor + (rating === 'easy' ? 0.15 : rating === 'hard' ? -0.15 : 0)); } review.rating = rating; review.reviewCount += 1; review.lastReviewedAt = new Date().toISOString(); review.dueAt = new Date(Date.now() + (rating === 'again' ? 10 * 60000 : review.intervalDays * 86400000)).toISOString(); card.review = review; currentState.progress.cardReviews.push({ id:uid('review'), deckId:deck.id, cardId:card.id, rating, dateKey:todayKey(), reviewedAt:review.lastReviewedAt }); persistState(); if (reviewState.cardIndex >= deck.cards.length - 1) { reviewState = { deckId:null, cardIndex:0, revealed:false }; showToast('Deck review complete.'); } else { reviewState.cardIndex += 1; reviewState.revealed = false; } renderApp(); showPage('flashcards'); }
