  const input = $('#note-import-subject');
  if (input) input.value = currentState.subjects.length ? currentState.subjects[0].name : '';
  const count = $('#note-import-count');
  if (count) count.textContent = pendingNoteFiles.length === 1 ? '1 file selected' : `${pendingNoteFiles.length} files selected`;
  const error = $('#note-import-error');
  if (error) error.textContent = '';
